package cn.tbforum.repo;
import cn.tbforum.domain.*; import org.springframework.data.domain.Page; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
public final class Repositories {
 private Repositories() {}
 public interface Users extends JpaRepository<User,Long>{ Optional<User> findByUsername(String username); List<User> findTop10ByUsernameContainingIgnoreCase(String username); }
 public interface Forums extends JpaRepository<Forum,Long>{ Optional<Forum> findBySlug(String slug); }
 public interface Posts extends JpaRepository<Post,Long>{ Page<Post> findByForumAndDeletedFalse(Forum forum,org.springframework.data.domain.Pageable p); Page<Post> findByForumAndFeaturedTrueAndDeletedFalse(Forum forum,org.springframework.data.domain.Pageable p); List<Post> findByForumAndDeletedFalse(Forum forum); Page<Post> findByAuthorAndDeletedFalse(User author,org.springframework.data.domain.Pageable p); Page<Post> findAllByDeletedFalseOrderByCreatedAtDesc(org.springframework.data.domain.Pageable p); Page<Post> findByFeaturedTrueAndDeletedFalse(org.springframework.data.domain.Pageable p); List<Post> findByDeletedFalse(); @Query("select p from Post p where p.deleted=false and (lower(p.title) like lower(concat('%',:q,'%')) or lower(p.content) like lower(concat('%',:q,'%')))") Page<Post> search(@Param("q") String q,org.springframework.data.domain.Pageable p); @Query("select p from Post p where p.deleted=false and p.createdAt>=:since order by (p.upvotes + p.commentCount*0.5 + p.views*0.01) desc") List<Post> findHotSince(@Param("since") Instant since); }
 public interface Comments extends JpaRepository<Comment,Long>{ List<Comment> findByPostAndDeletedFalseOrderByCreatedAtAsc(Post post); List<Comment> findByPostAndDeletedFalseOrderByPinnedDescCreatedAtAsc(Post post); }
 public interface Moderators extends JpaRepository<ForumModerator,Long>{ long countByForum(Forum forum); boolean existsByForumAndUser(Forum f,User u); List<ForumModerator> findByForum(Forum forum); @Transactional void deleteByForumAndUser(Forum f,User u); }
 public interface Interactions extends JpaRepository<Interaction,Long>{ Optional<Interaction> findByUserAndPost(User u,Post p); List<Interaction> findByUserAndKind(User u,Interaction.Kind kind); }
 public interface Notifications extends JpaRepository<Notification,Long>{ List<Notification> findTop20ByUserOrderByCreatedAtDesc(User user); long countByUserAndReadFalse(User user); List<Notification> findByUserAndReadFalse(User user); }
 public interface Follows extends JpaRepository<Follow,Long>{ Optional<Follow> findByFollowerAndFollowee(User follower,User followee); long countByFollowee(User followee); long countByFollower(User follower); List<Follow> findByFollowerOrderByCreatedAtDesc(User follower); List<Follow> findByFolloweeOrderByCreatedAtDesc(User followee); @Transactional void deleteByFollowerAndFollowee(User follower,User followee); }
 public interface Favorites extends JpaRepository<Favorite,Long>{ Optional<Favorite> findByUserAndPost(User u,Post p); boolean existsByUserAndPost(User u,Post p); @Transactional void deleteByUserAndPost(User u,Post p); @Query("select f.post from Favorite f where f.user=:u and f.post.deleted=false order by f.createdAt desc") Page<Post> findPostsByUser(@Param("u") User u,org.springframework.data.domain.Pageable p); }
 public interface Reports extends JpaRepository<Report,Long>{ Page<Report> findByStatusOrderByCreatedAtDesc(Report.Status status,org.springframework.data.domain.Pageable p); Page<Report> findAllByOrderByCreatedAtDesc(org.springframework.data.domain.Pageable p); boolean existsByReporterAndTargetTypeAndTargetId(User reporter,Report.TargetType type,Long targetId); long countByStatus(Report.Status status); List<Report> findByTargetTypeAndTargetId(Report.TargetType type,Long targetId); }
 public interface Tags extends JpaRepository<Tag,Long>{ Optional<Tag> findByName(String name); List<Tag> findTop50ByOrderByPostCountDesc(); @Query("select t from Tag t order by t.postCount desc") List<Tag> findPopular(@Param("limit") int limit); }
 public interface PostTags extends JpaRepository<PostTag,Long>{ List<PostTag> findByPost(Post post); List<PostTag> findByTag(Tag tag); @Query("select pt.post from PostTag pt where pt.tag=:tag and pt.post.deleted=false order by pt.post.createdAt desc") Page<Post> findPostsByTag(@Param("tag") Tag tag,org.springframework.data.domain.Pageable p); @Transactional void deleteByPost(Post post); }
}


